#ifndef JEXPLAIN_H
#define JEXPLAIN_H

/* `ashvm explain E0101` / `kiln --explain E0101`: the entry of an error code from docs/MEMORY_SAFETY.md
 * ("Error codes"), compiled in (explain_data.c is generated by tools/gen_explain.sh). */

typedef struct {
    const char *code;
    const char *title;
    const char *text;
} JExplain;

extern const JExplain jexplain_table[];     /* ends with a {0, 0, 0} entry */

/* Prints the entry of `code` (case-insensitive) to stdout and returns 0; with a NULL code lists them all.
 * An unknown code prints a message on stderr and returns 1. */
int jexplain_print(const char *code);

#endif
